import './style.css';
import {probeBackend,validateBackendOrigin} from './connection.ts';
type GameMount = typeof import('./game.ts').mountGame;
import type { GameInput, MatchState } from '../core/cricket.ts';
import { minimumBid } from '../core/auction.ts';
import { CRORE,TEAM_PURSE,PLAYER_CAP,formatMoney,parseCrores } from '../core/money.ts';

type Row = Record<string, any>;
type Page = 'Home'|'Create Tournament'|'Join Tournament'|'Live Auctions'|'My Franchise'|'My Squad'|'Fixtures'|'Live Matches'|'Points Table'|'Playoffs'|'Leaderboard'|'Practice'|'Settings';
const root = document.querySelector<HTMLDivElement>('#app')!;
const icons:Record<string,string> = {
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>', trophy:'<path d="M8 3h8v7a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v6m-4 1h8"/>', plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>', users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 6"/>', auction:'<path d="m13 3 8 8m-9-7-5 5 7 7 5-5M3 21l8-8m-8 6 2 2m10 0h7"/>', calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-14 4h3m4 0h3"/>', play:'<path d="m9 5 11 7-11 7Z"/><path d="M3 4v16"/>', chart:'<path d="M4 21V10m8 11V3m8 18V7"/>', settings:'<path d="m9 3-1 3-3 1v4l-2 2 2 3 3 1 1 4h5l1-3 4-1 2-4-2-3-1-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>', shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>', bolt:'<path d="m14 2-10 12h7l-1 8 10-12h-7Z"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>', globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z"/>', grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>', ball:'<circle cx="12" cy="12" r="9"/><path d="M6 5c7 1 11 6 12 13M4 8c6 0 11 5 12 12"/>', check:'<path d="m5 12 4 4L19 6"/>', wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r="1"/>', link:'<path d="m9 15 6-6m-6-3 3-3a5 5 0 0 1 7 7l-3 3m-1 5-3 3a5 5 0 0 1-7-7l3-3"/>'
};
const icon=(name:string)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const money=(n:unknown)=>{const value=Number(n)||0;return selected?.currency==='INR_LAKH'?formatMoney(value):new Intl.NumberFormat('en-IN',{maximumFractionDigits:0}).format(value)+' legacy credits';};
const short=(name:unknown)=>String(name||'Team').split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const pretty=(s:unknown)=>String(s||'').replaceAll('_',' ').toLowerCase().replace(/^./,s=>s.toUpperCase());
let page:Page='Home';
let tournaments:Row[]=[];
let selected:Row|null=null;
let detailTab='Overview';
const hostedApi='https://acpl-match-server.onrender.com';
let apiBase=localStorage.getItem('acpl-api')||(location.hostname.endsWith('.chatgpt.site')?hostedApi:'');
let token=localStorage.getItem('acpl-token')||'';
let user:Row|null=null;
try{user=JSON.parse(localStorage.getItem('acpl-user')||'null')}catch{/* invalid local state */}
let connected=false;
let socket:WebSocket|null=null;
let reconnectTimer:ReturnType<typeof setTimeout>|undefined;
let toastTimer:ReturnType<typeof setTimeout>|undefined;
let game:ReturnType<GameMount>|null=null;
let activeMatchId:string|null=null;
let sequence=0;
let loading=false;
let modalAfter:(()=>void)|null=null;
const navItems:[Page,string][]=[['Home','home'],['Create Tournament','plus'],['Join Tournament','link'],['Live Auctions','auction'],['My Franchise','shield'],['My Squad','users'],['Fixtures','calendar'],['Live Matches','play'],['Points Table','chart'],['Playoffs','trophy'],['Leaderboard','chart'],['Practice','ball']];
function notify(text:string,error=false){document.querySelector('.toast')?.remove();clearTimeout(toastTimer);const el=document.createElement('div');el.className='toast'+(error?' error':'');el.role='status';el.textContent=text;document.body.append(el);toastTimer=setTimeout(()=>el.remove(),6000)}
async function api(path:string,method='GET',data?:unknown):Promise<any>{
 const headers:Record<string,string>={'Content-Type':'application/json'};if(token)headers.Authorization=`Bearer ${token}`;
 let response:Response;
 try{response=await fetch(`${apiBase}${path}`,{method,headers,body:data===undefined?undefined:JSON.stringify(data),signal:AbortSignal.timeout(12000)})}catch{connected=false;throw new Error('The match server is unavailable. Practice runs locally in your browser. Set your server address in Settings to connect.');}
 let result:any;try{result=await response.json()}catch{connected=false;throw new Error('No cricket server at this address. Open Settings to connect a running backend.');}
 if(!response.ok){if(response.status===401&&path!=='/api/login'&&path!=='/api/register'){clearSession()}throw new Error(result.error||result.message||`Request failed (${response.status})`)}
 connected=true;return result;
}
function requireIdentity(next:()=>void){if(user&&token){next();return}modalAfter=next;showIdentity()}
function clearSession(){token='';user=null;localStorage.removeItem('acpl-token');localStorage.removeItem('acpl-user');socket?.close();socket=null;clearTimeout(reconnectTimer);tournaments=[];selected=null;connected=false;}
async function refresh(){if(!token)return;loading=true;render();try{user=await api('/api/me');localStorage.setItem('acpl-user',JSON.stringify(user));const data=await api('/api/tournaments');tournaments=Array.isArray(data)?data:data.tournaments||[];if(selected){selected=await api(`/api/tournaments/${selected.id}`)}connectSocket()}catch(e){notify((e as Error).message,true)}finally{loading=false;render()}}
function connectSocket(){if(!token||socket?.readyState===WebSocket.OPEN||socket?.readyState===WebSocket.CONNECTING)return;clearTimeout(reconnectTimer);let url:URL;try{url=new URL(apiBase||location.origin);url.protocol=url.protocol==='https:'?'wss:':'ws:';url.pathname='/ws';url.search=`token=${encodeURIComponent(token)}`}catch{return}
 socket=new WebSocket(url);const currentSocket=socket;
 socket.onopen=()=>{if(socket!==currentSocket)return;connected=true;if(selected)socket?.send(JSON.stringify({type:'subscribe',tournamentId:selected.id}));if(activeMatchId)socket?.send(JSON.stringify({type:'joinMatch',matchId:activeMatchId}));renderConnection()};
 socket.onmessage=e=>{if(socket!==currentSocket)return;try{const msg=JSON.parse(e.data);if(msg.type==='tournament'){const data=msg.data;if(data?.id){const i=tournaments.findIndex(t=>t.id===data.id);if(i>=0)tournaments[i]=data;else tournaments.push(data);if(selected?.id===data.id)selected=data;if(!game)render()}}else if(msg.type==='match'){if(msg.data?.id===activeMatchId){sequence=Math.max(sequence,Number(msg.data.sequence?.[String(user?.id)]??-1));game?.update(msg.data as MatchState)}}else if(msg.type==='error'){notify(msg.data?.message||msg.error||msg.message||'Match action rejected',true)}}catch{/* malformed remote frame ignored */}};
 socket.onclose=()=>{if(socket!==currentSocket)return;connected=false;renderConnection();if(token)reconnectTimer=setTimeout(()=>{if(socket!==currentSocket)return;socket=null;connectSocket()},3500)};
 socket.onerror=()=>{if(socket!==currentSocket)return;connected=false;renderConnection()};
}
function renderConnection(){const el=document.querySelector('.connection');if(el)el.innerHTML=`<span class="dot ${connected?'connected':''}"></span>${connected?'Server connected':'Local practice available'}`}
function nav(to:Page){page=to;selected=null;document.querySelector('.sidebar')?.classList.remove('open');if(to==='Practice'){launchGame();page='Home'}else if(to==='Create Tournament'){requireIdentity(()=>showCreate());page='Home'}else if(to==='Join Tournament'){requireIdentity(()=>showJoin());page='Home'}render()}
const btn=(label:string,action:string,kind='dark',ico?:string,extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${esc(label)}</button>`;
function render(){if(game)return;root.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#" data-page="Home"><span class="brand-mark">A</span><span>ACPL<small>AUCTION CRICKET PREMIER LEAGUE</small></span></a><div class="nav-group">THE CLUBHOUSE</div><nav class="nav">${navItems.map(([name,ico])=>`<button data-page="${name}" class="${page===name?'active':''}">${icon(ico)}<span>${name}</span>${name==='Live Auctions'&&tournaments.some(t=>t.status==='AUCTION')?`<span class="count">${tournaments.filter(t=>t.status==='AUCTION').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="season-card"><div class="tag">FROM BID TO BOUNDARY</div><p>Build a squad.<br>Make it a champion.</p><button data-page="Practice">Meet your next match ↗</button></div><nav class="nav" style="margin-top:15px"><button data-page="Settings" class="${page==='Settings'?'active':''}">${icon('settings')}Settings</button></nav><div class="tiny">ACPL · Development build 0.3<br>Original teams. Real competition.</div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><div class="breadcrumbs">Clubhouse <span style="padding:0 12px;color:#bdc5b7">/</span> <strong>${esc(selected?.name||page)}</strong></div><div class="top-actions"><div class="connection"><span class="dot ${connected?'connected':''}"></span>${connected?'Server connected':'Local practice available'}</div><button class="account" data-action="identity"><span class="avatar">${short(user?.name||'Guest')}</span><span>${esc(user?.name||'Your clubhouse')}<small>${user?(user.accountType==='account'?'Password account':'Guest account'):'Sign in / Create account'} ⌄</small></span></button></div></header><div class="content">${selected?renderDetail():renderPage()}</div></main></div>`;bindForms()}
function heading(title:string,sub:string,actions=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR CRICKET. YOUR CALL.</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${actions?`<div class="button-row">${actions}</div>`:''}</div>`}
function empty(title:string,copy:string,action='',ico='trophy'){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`}
function renderPage():string{
 if(page==='Settings')return renderSettings();
 if(page==='Home')return renderHome();
 if(page==='Live Auctions')return heading('The auction room','Where a championship squad begins.',btn('Create tournament','create','dark','plus'))+renderTournamentCards(tournaments.filter(t=>t.status==='AUCTION'),'No auctions live yet','Create a tournament and open bidding, or join a friend’s league.');
 if(page==='My Franchise'||page==='My Squad'){const mine=tournaments.filter(t=>t.teams?.some((team:Row)=>team.ownerId===user?.id));return heading(page==='My Squad'?'Your squad, your strategy.':'The franchise desk','Manage the players and franchises you own.')+renderTournamentCards(mine,'Your franchise starts here','Join a tournament, name your franchise, and build your squad in the auction.');}
 if(page==='Fixtures'||page==='Live Matches'){const fixtures=tournaments.flatMap(t=>(t.fixtures||[]).filter((f:Row)=>page!=='Live Matches'||f.status==='LIVE').map((f:Row)=>({...f,tournament:t})));return heading(page==='Fixtures'?'The road to the final.':'Live from the middle',page==='Fixtures'?'Schedules, opponents, and every match that matters.':'Independent matches. One shared love of cricket.')+(fixtures.length?fixtures.map(f=>renderFixture(f,f.tournament)).join(''):`<div class="panel">${empty('The pitch is waiting',page==='Fixtures'?'Fixtures appear after squads are finalized and the host generates a schedule.':'Live matches appear here when the host starts a fixture.',btn('Find a tournament','join','outline','link'),'calendar')}</div>`)}
 if(page==='Points Table'||page==='Leaderboard'||page==='Playoffs')return heading(page==='Playoffs'?'Earn your place in the final.':page==='Leaderboard'?'The championship race.':'Every run counts.',page==='Playoffs'?'Qualifiers, eliminator, and the grand final.':'Open a tournament for verified results and standings.')+renderTournamentCards(tournaments,'A clean slate','Standings and records appear after completed server-verified matches.');
 return renderHome();
}
function renderHome(){const own=tournaments.filter(t=>t.teams?.some((team:Row)=>team.ownerId===user?.id));const live=tournaments.flatMap(t=>t.fixtures||[]).filter(f=>f.status==='LIVE').length;const won=tournaments.filter(t=>t.championId&&t.teams?.find((x:Row)=>x.id===t.championId)?.ownerId===user?.id).length;return `${heading(user?`Welcome back, ${user.name.split(' ')[0]}.`:'Welcome to your clubhouse.','A great league begins with you.',btn('Join a league','join','outline','link')+btn('Create tournament','create','dark','plus'))}<section class="hero"><div class="hero-copy"><div class="eyebrow">THE GAME IS YOURS</div><h2>Own the team.<br><em>Rule the pitch.</em></h2><p>Win the auction. Build your playing XI. Take control in 3D and turn your franchise into a champion.</p><div class="button-row">${btn('Build your league','create','primary','plus')}${btn('Try the nets','practice','white','play')}</div><div class="hero-foot">${icon('shield')}Original fictional players <span style="padding:0 5px">·</span> Playable browser cricket</div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="pitch-art"></div><div class="bat-art"></div><div class="ball-art"></div><div class="art-label">YOUR LEGACY STARTS HERE</div></div></section><section class="metrics">${[['shield',own.length,'YOUR FRANCHISES'],['auction',tournaments.filter(t=>t.status==='AUCTION').length,'ACTIVE AUCTIONS'],['play',live,'LIVE MATCHES'],['trophy',won,'CHAMPIONSHIPS']].map(([ico,n,label])=>`<div class="metric"><div class="metric-icon">${icon(String(ico))}</div><div><strong>${n}</strong><small>${label}</small></div></div>`).join('')}</section><div class="dashboard-columns"><section><div class="section-title"><h2>Your tournaments</h2><button class="text-button" data-action="refresh">Refresh ${icon('arrow')}</button></div>${loading?'<div class="panel"><div class="spinner"></div></div>':tournaments.length?renderTournamentCards(tournaments.slice(0,2),'',''):`<div class="panel">${empty('Your next rivalry starts here.','Create a private league for your friends, or join a tournament with an invite code.',btn('Create your first tournament','create','dark','plus'))}</div>`}</section><section><div class="section-title"><h2>One league. A whole journey.</h2><span class="mini">THE PLAYBOOK</span></div><div class="panel journey">${[['01','Build your franchise','Create a league, invite your rivals, and claim your team.'],['02','Win the auction','Bid live for the players that fit your game plan.'],['03','Take the field','Choose your XI and control the action in 3D.'],['04','Lift the trophy','Climb the table, survive the playoffs, win the final.']].map(([n,title,copy])=>`<div class="journey-step"><span class="step-number">${n}</span><div><h4>${title}</h4><p>${copy}</p></div></div>`).join('')}</div></section></div><div class="bottom-banner">${icon('ball')}<div><strong>Before the auction, find your timing.</strong><p>Try batting and bowling in the practice nets. No account needed.</p></div><button class="text-button" data-action="practice">Go to practice ${icon('arrow')}</button></div>${!connected?'<div class="status-note">Practice runs on this device. Multiplayer tournaments require the Node match server. Connect it in <button class="text-button" data-page="Settings">Settings ↗</button>. This development build does not yet include every rule, animation, or native platform in the full specification.</div>':''}`}
function renderTournamentCards(items:Row[],title:string,copy:string){return items.length?`<div class="cards">${items.map(t=>`<article class="tournament-card"><div class="tournament-cover"><span class="badge dark">${pretty(t.status)}</span><h3>${esc(t.name)}</h3></div><div class="card-body"><div class="card-meta"><span>${(t.teams||[]).filter((tm:Row)=>tm.ownerId).length} / ${t.teamCount||10} franchises</span><span>${t.overs||20} overs</span></div>${btn('Enter clubhouse','open','outline','arrow',`data-id="${esc(t.id)}"`)}</div></article>`).join('')}</div>`:`<div class="panel">${empty(title,copy,btn('Join a tournament','join','outline','link'))}</div>`}
const myTeam=()=>selected?.teams?.find((t:Row)=>t.ownerId===user?.id);
const teamName=(id:unknown,t=selected)=>t?.teams?.find((team:Row)=>team.id===id)?.name||String(id||'To be decided');
const playerName=(id:unknown)=>selected?.players?.find((p:Row)=>p.id===id)?.name||String(id||'Unknown player');
function renderDetail(){const t=selected!;const host=t.hostId===user?.id;const tabs=['Overview','Auction','My Squad','Fixtures','Points Table','Playoffs'];return `<div class="section-title"><button class="text-button" data-action="back">← All tournaments</button><button class="text-button" data-action="refresh">Refresh ${icon('arrow')}</button></div><div class="detail-head"><div><span class="badge dark">${pretty(t.status)}</span><h2>${esc(t.name)}</h2><p>${t.teams.filter((tm:Row)=>tm.ownerId).length} / ${t.teamCount} owners · ${t.overs} overs · ${host?'You are the host':'Tournament participant'}</p></div><div class="button-row">${t.inviteCode?`<button class="btn outline" data-action="copy-code" style="color:#dbe6c5;border-color:#667959">${icon('link')}${esc(t.inviteCode)}</button>`:''}${!myTeam()&&t.status==='REGISTRATION'?btn('Claim franchise','claim','primary','plus'):''}</div></div><div class="detail-tabs">${tabs.map(tab=>`<button data-tab="${tab}" class="${detailTab===tab?'active':''}">${tab}</button>`).join('')}</div>${detailTab==='Auction'?renderAuction():detailTab==='My Squad'?renderSquad():detailTab==='Fixtures'?renderFixtures():detailTab==='Points Table'?renderStandings():detailTab==='Playoffs'?renderPlayoffs():renderOverview()}`}
function renderOverview(){const t=selected!;const host=t.hostId===user?.id;let controls='';if(host){if(t.status==='REGISTRATION')controls=btn('Open player auction','start-auction','dark','auction');if(t.status==='AUCTION')controls=btn('Validate squads & finish auction','finish-auction','dark','check');if(t.status==='SQUAD_VALIDATION')controls=`<form id="fixtures-form"><label class="field">Schedule format<select name="format"><option value="single">Single round robin</option><option value="double">Double round robin</option>${t.teamCount===10?'<option value="ipl">IPL-style · 70 league matches</option>':''}</select></label>${btn('Generate fixtures','submit-fixtures','dark','calendar','type="submit"')}</form>`;if(['LEAGUE_COMPLETED','PLAYOFFS','FINAL'].includes(t.status))controls=btn('Resolve playoff progression','advance-playoffs','dark','trophy')}
 return `<div class="split"><section class="panel"><div class="section-title"><h2>Franchise owners</h2><span class="mini">${t.teams.filter((tm:Row)=>tm.ownerId).length} OWNERS</span></div>${t.teams.length?t.teams.map((team:Row)=>`<div class="team-row"><div class="team-token">${short(team.name)}</div><div class="team-info"><strong>${esc(team.name)} ${team.ownerId===user?.id?'<span class="badge">YOU</span>':''}</strong><small>${!team.ownerId?'Vacant franchise':`${team.roster?.length||0} players · ${team.ready?'Playing XI ready':'Squad in progress'}`}</small></div><span>${money(team.purse)}</span></div>`).join(''):empty('The first franchise is yours.','Claim your franchise to take part in the auction.',btn('Claim franchise','claim','dark','shield'))}</section><section class="panel"><div class="section-title"><h2>${host?'Tournament control':'League information'}</h2></div><p class="helper">${host?'You control auction nominations, fixture generation, and match starts. Purchased players and verified results are controlled by the server.':'All bids, ownership, match actions, and results are validated by the authoritative server.'}</p><div class="team-row"><span>League status</span><span class="badge">${pretty(t.status)}</span></div><div class="team-row"><span>Match length</span><strong>${t.overs} overs</strong></div><div class="team-row"><span>Teams</span><strong>${t.teamCount}</strong></div>${controls?`<div style="margin-top:22px">${controls}</div>`:''}${t.championId?`<div class="champion" style="margin-top:20px"><div class="trophy">🏆</div><h2>${esc(teamName(t.championId))}</h2><p>Tournament champions</p></div>`:''}</section></div>`}
function renderAuction(){const t=selected!;const auction=t.auction||{};const current=auction.current;const player=t.players?.find((p:Row)=>p.id===current?.playerId);const host=t.hostId===user?.id;const own=myTeam();const owned=new Set(t.teams.flatMap((tm:Row)=>tm.roster||[]));const players=(t.players||[]).filter((p:Row)=>!owned.has(p.id));const lot=current?.status==='OPEN';const base=player?.basePrice||100;const top=Number(current?.highestBid||0),modern=t.currency==='INR_LAKH',capped=top>=PLAYER_CAP;let nextBid=base;if(lot&&!capped)try{nextBid=minimumBid(auction,t.players);}catch{nextBid=PLAYER_CAP;}const lead=!!own&&current?.highestTeamId===own.id;const bidValue=modern?(nextBid/CRORE).toFixed(2):String(nextBid);return `${t.status!=='AUCTION'?'<div class="notice">Bidding opens when the host starts the auction.</div>':''}<div class="notice">${modern?`${formatMoney(TEAM_PURSE)} virtual purse per team · ${formatMoney(PLAYER_CAP)} maximum purchase price per player. No real money is collected.`:'Legacy tournament: original integer-credit balances are preserved. New tournaments use a ₹120 Cr virtual purse and ₹20 Cr player cap.'}</div><div class="split"><div class="player-card">${player?`<span class="badge">${esc(current.status)} · ${esc(player.role)}</span><div class="player-portrait" style="margin-top:25px">${short(player.name)}</div><h2>${esc(player.name)}</h2><p>${esc(player.battingStyle||'Right hand')} · ${esc(player.bowlingStyle||player.role)} ${player.overseas?'· Overseas':''}</p><div class="rating-grid">${[['BATTING',player.batting??player.battingRating],['BOWLING',player.bowling??player.bowlingRating],['POWER',player.power??player.powerRating]].map(([label,n])=>`<div><strong>${n??'—'}</strong><small>${label}</small></div>`).join('')}</div><p>${top?'CURRENT BID':'BASE PRICE'}</p><div class="auction-price">${money(top||base)}</div><p>${current.highestTeamId?`Leading: ${esc(teamName(current.highestTeamId))}`:'Awaiting first bid'}</p><div class="auction-clock" data-deadline="${Number(current.deadline)||0}">${lot?'Bidding live':'Lot closed'}</div>${own&&lot&&!capped&&!lead?`<form id="bid-form"><label class="field" style="text-align:left">${modern?'Your bid (crore, virtual funds)':'Your bid (legacy integer credits)'}<input name="amount" type="number" min="${bidValue}" max="${modern?PLAYER_CAP/CRORE:PLAYER_CAP}" step="${modern?'0.01':'1'}" value="${bidValue}" required/></label>${btn('Place bid','submit-bid','dark','auction','type="submit"')}</form>`:own&&lot&&capped?`<p class="cap-reached">${modern?formatMoney(PLAYER_CAP):'Maximum bid'} cap reached. Awaiting server settlement.</p>`:own&&lot&&lead?'<p class="cap-reached">Your franchise leads this lot.</p>':!own?'<p>Claim a franchise during registration to bid.</p>':''}${host&&lot?`<div style="margin-top:17px">${btn('Close lot after deadline','close-lot','outline','clock')}</div>`:''}`:empty('Your squad starts with a bid.','The host selects the next player from the catalog to open a live lot.',host&&t.status==='REGISTRATION'?btn('Open auction','start-auction','dark','auction'):'','auction')}</div><div><section class="panel"><div class="section-title"><h2>Player catalog</h2><span class="mini">${players.length} AVAILABLE</span></div><div class="scroll-list">${players.map((p:Row)=>`<div class="player-row"><div class="team-token">${short(p.name)}</div><div class="team-info"><strong>${esc(p.name)}</strong><small>${esc(p.role)} · ${money(p.basePrice||100)}</small></div>${host&&t.status==='AUCTION'?btn('Nominate','nominate','outline',undefined,`data-id="${esc(p.id)}" ${lot?'disabled':''}`):''}</div>`).join('')}</div></section><section class="panel" style="margin-top:18px"><div class="section-title"><h2>Live bid history</h2></div>${current?.bids?.length?current.bids.slice(-6).reverse().map((b:Row)=>`<div class="team-row"><span>${esc(teamName(b.teamId))}</span><strong>${money(b.amount)}</strong></div>`).join(''):'<p class="helper">The first accepted bid will appear here.</p>'}</section></div></div>`}
function renderSquad(){const team=myTeam();if(!team)return `<div class="panel">${empty('You need a franchise first.','Join this tournament during registration to buy and select players.','','users')}</div>`;const roster=(selected!.players||[]).filter((p:Row)=>team.roster.includes(p.id));return `<div class="split"><section class="panel"><div class="section-title"><h2>${esc(team.name)}</h2><span class="badge">${roster.length} OWNED PLAYERS</span></div><p class="helper">Select exactly 11 purchased players. Choose a captain and an eligible wicketkeeper, then confirm your team. The server checks ownership and squad rules.</p>${roster.length?`<form id="xi-form"><div class="scroll-list">${roster.map((p:Row)=>`<label class="player-row"><input type="checkbox" name="players" value="${esc(p.id)}" ${team.xi?.includes(p.id)?'checked':''}/><div class="team-info"><strong>${esc(p.name)}</strong><small>${esc(p.role)}${p.overseas?' · Overseas':''}</small></div><span class="badge">BAT ${p.batting??p.battingRating??'—'} / BWL ${p.bowling??p.bowlingRating??'—'}</span></label>`).join('')}</div><div class="form-grid" style="margin-top:20px"><label class="field">Captain<select name="captainId">${roster.map((p:Row)=>`<option value="${esc(p.id)}" ${team.captainId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Wicketkeeper<select name="keeperId">${roster.filter((p:Row)=>/keep|wk/i.test(p.role)||Number(p.wicketkeeping)>50).map((p:Row)=>`<option value="${esc(p.id)}" ${team.keeperId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div>${btn('Confirm playing XI','submit-xi','dark','check','type="submit"')}</form>`:empty('Build a squad at the auction.','Every player purchased by your franchise appears here.',`<button class="btn outline" data-tab="Auction">Enter auction</button>`,'auction')}</section><section class="panel"><div class="section-title"><h2>Match readiness</h2></div><div class="team-row"><span>Purchased players</span><strong>${roster.length}</strong></div><div class="team-row"><span>Selected in XI</span><strong>${team.xi?.length||0} / 11</strong></div><div class="team-row"><span>Wicketkeeper</span><strong>${team.keeperId?esc(playerName(team.keeperId)):'Not selected'}</strong></div><div class="team-row"><span>Captain</span><strong>${team.captainId?esc(playerName(team.captainId)):'Not selected'}</strong></div><div class="status-note">${team.ready?'Your playing XI is validated and ready.':'Finalize a legal XI before fixtures can be generated.'}</div></section></div>`}
function renderFixtures(){return selected!.fixtures?.length?selected!.fixtures.map((f:Row)=>renderFixture(f,selected!)).join(''):`<div class="panel">${empty('The schedule comes next.','After all squads are ready, the host can generate a mathematically validated schedule.','','calendar')}</div>`}
function renderFixture(f:Row,t:Row){const host=t.hostId===user?.id;return `<div class="fixture"><span class="badge">${pretty(f.stage||'LEAGUE')} · ${f.round||f.matchNumber||'—'}</span><div class="teams">${esc(teamName(f.teamAId,t))}<span>VS</span>${esc(teamName(f.teamBId,t))}<small>${esc(t.name)} · ${pretty(f.status)}${f.result?.winnerId?` · Won by ${esc(teamName(f.result.winnerId,t))}`:''}</small></div>${f.matchId?`<div class="button-row">${btn(f.status==='COMPLETED'?'View 3D result':'Enter match','enter-match','dark','play',`data-id="${esc(f.matchId)}"`)}${btn('Scorecard','scorecard','outline','chart',`data-id="${esc(f.matchId)}"`)}</div>`:host&&f.status==='PENDING'?btn('Start match','start-match','outline','play',`data-id="${esc(f.id)}" data-tournament="${esc(t.id)}"`):''}</div>`}
function renderStandings(){const rows=selected!.standings||[];return `<section class="panel"><div class="section-title"><h2>League standings</h2><span class="mini">SERVER-VERIFIED RESULTS</span></div><div class="table-wrap"><table><thead><tr><th>Pos</th><th>Franchise</th><th>P</th><th>W</th><th>L</th><th>T</th><th>NR</th><th>Points</th><th>NRR</th></tr></thead><tbody>${rows.map((s:Row,i:number)=>`<tr><td>${s.rank||i+1}</td><td><strong>${esc(teamName(s.teamId))}</strong></td><td>${s.played??s.matchesPlayed??0}</td><td>${s.wins||0}</td><td>${s.losses||0}</td><td>${s.ties||0}</td><td>${s.noResults||0}</td><td><strong>${s.points||0}</strong></td><td>${Number(s.nrr??s.netRunRate??0).toFixed(3)}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('The table is ready for its first result.','Standings update when an authoritative match result is committed.','','chart'):''}<p class="helper">Net run rate uses aggregate innings runs and legal-ball denominators, including the configured full quota for all-out innings.</p></section>`}
function renderPlayoffs(){const fs=selected!.fixtures||[];const stages=['Q1','ELIMINATOR','Q2','FINAL'];const card=(stage:string)=>{const f=fs.find((f:Row)=>f.stage===stage);return `<div class="bracket-card"><span class="badge">${stage==='FINAL'?'THE GRAND FINAL':pretty(stage==='Q1'?'QUALIFIER_1':stage==='Q2'?'QUALIFIER_2':stage)}</span><h3>${stage==='FINAL'?'One match. One champion.':stage==='Q2'?'The second chance.':stage==='Q1'?'The first ticket.':'Win or go home.'}</h3><div class="bracket-team">${esc(f?teamName(f.teamAId):stage==='Q1'?'League rank 1':stage==='ELIMINATOR'?'League rank 3':stage==='Q2'?'Qualifier 1 loser':'Qualifier 1 winner')}</div><div class="bracket-team">${esc(f?teamName(f.teamBId):stage==='Q1'?'League rank 2':stage==='ELIMINATOR'?'League rank 4':stage==='Q2'?'Eliminator winner':'Qualifier 2 winner')}</div><p>${f?pretty(f.status):'Awaiting confirmed qualifiers'}</p>${f?.matchId?`<button class="text-button" style="margin-top:15px" data-action="enter-match" data-id="${esc(f.matchId)}">Enter match →</button>`:f&&selected!.hostId===user?.id?`<button class="text-button" style="margin-top:15px" data-action="start-match" data-id="${esc(f.id)}">Start match →</button>`:''}</div>`};return `${selected!.championId?`<div class="champion"><div class="trophy">🏆</div><h2>${esc(teamName(selected!.championId))}</h2><p>ACPL champions. The league belongs to you.</p></div>`:''}<div class="notice">Slots are confirmed by the server only after their dependency matches are complete. For fewer than four teams, the configured smaller bracket applies.</div><div class="bracket"><div class="bracket-round">${card(stages[0])}${card(stages[1])}</div><div class="bracket-round">${card(stages[2])}</div><div class="bracket-round">${card(stages[3])}</div></div>`}
function renderSettings(){return `${heading('Make yourself at home.','Your account and match server connection.')}<div class="split"><section class="panel"><div class="section-title"><h2>Match server connection</h2></div><p class="helper">The hosted website includes local 3D practice. Live accounts, auctions and online matches require the match server. Leave the address blank when this website is served by that backend.</p><form id="settings-form"><label class="field">Backend origin<input name="apiBase" type="url" value="${esc(apiBase)}" placeholder="https://your-cricket-server.example"/></label><p class="helper">Use HTTPS for remote servers. A public HTTPS page cannot connect to an insecure remote HTTP server. For local development, open the frontend on the backend’s own localhost address.</p><div class="button-row">${btn('Test connection','test-connection','outline','wifi','type="button"')}${btn('Save connection','submit-settings','dark','check','type="submit"')}</div><p class="helper" id="connection-result" role="status" aria-live="polite"></p></form></section><section class="panel"><div class="section-title"><h2>Your account</h2></div>${user?`<div class="team-row"><span>Username</span><strong>${esc(user.name)}</strong></div><div class="team-row"><span>Account type</span><strong>${user.accountType==='account'?'Username and password':'Persistent guest'}</strong></div><div class="team-row"><span>Account ID</span><span class="code">${esc(user.id)}</span></div><p class="helper">${user.accountType==='account'?'Sign in with your username and password on another device to access this same account and your franchises. Passwords are never saved in this browser. Signing out revokes this session.':'This guest identity stays with this browser. Clearing browser data loses guest access. A new password account is separate from your guest history; guest migration is not available yet.'}</p>${btn('Sign out','signout','outline')}`:`<p class="helper">Use your own username and password to keep your franchises and tournament history under one account. Practice requires no account.</p><div class="button-row">${btn('Sign in','identity','dark','users')}${btn('Create account','register','outline')}</div>`}</section></div><div class="status-note">Virtual auction rules · ${formatMoney(TEAM_PURSE)} purse per franchise · ${formatMoney(PLAYER_CAP)} maximum per player. These are game funds; no real-money payment is collected. Browser 3D and native-device validation remain in development.</div>`}
function showModal(title:string,body:string){document.querySelector('.modal-shade')?.remove();const el=document.createElement('div');el.className='modal-shade';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Close dialog">×</button></div>${body}</section>`;document.body.append(el);bindForms();setTimeout(()=>el.querySelector<HTMLInputElement>('input')?.focus(),0)}
function closeModal(){document.querySelector('.modal-shade')?.remove()}
function showIdentity(mode:'login'|'register'|'guest'='login'){const register=mode==='register',guest=mode==='guest';showModal(guest?'Guest clubhouse identity':register?'Create your ACPL account':'Welcome back to ACPL',`<div class="auth-tabs"><button type="button" data-action="login" class="${mode==='login'?'active':''}">Sign in</button><button type="button" data-action="register" class="${register?'active':''}">Create account</button></div><p class="helper">${guest?'Guests stay with this browser. Create a password account to sign in on another device.':register?'Choose your own username and password. Your franchises and tournament records belong to this account.':'Sign in to access your own franchises, purchased squads and tournament history.'}</p><form id="identity-form" data-auth-mode="${mode}"><label class="field">Username<input name="name" autocomplete="username" minlength="${guest?2:3}" maxlength="32" ${guest?'':'pattern="[A-Za-z0-9_-]{3,32}"'} placeholder="Your cricket username" required/></label>${guest?'':`<label class="field">Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="10" maxlength="128" placeholder="${register?'At least 10 characters':'Your account password'}" required/></label>${register?'<label class="field">Confirm password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" maxlength="128" required/></label>':''}<p class="helper">${register?'Username: 3–32 letters, numbers, underscores or hyphens. Password: 10–128 characters.':'Usernames are case-insensitive. Password recovery is not available yet.'}</p>`}<div class="form-footer">${btn(guest?'Continue as guest':register?'Create account':'Sign in','submit-identity','dark','arrow','type="submit"')}</div></form><div class="auth-footer">${guest?'<button class="text-button" type="button" data-action="login">Use a password account instead</button>':'<button class="text-button" type="button" data-action="guest">Continue as a guest on this device</button>'}<button class="text-button" type="button" data-action="practice-from-auth">Try practice without an account →</button></div>`)}
function showCreate(){showModal('Build your league',`<p class="helper">Invite your friends, auction fictional players, and compete for a championship.</p><form id="create-form"><label class="field">Tournament name<input name="name" minlength="3" maxlength="64" placeholder="The Weekend Premier League" required/></label><div class="form-grid"><label class="field">Franchises<select name="teamCount">${[2,4,6,8,10].map(n=>`<option value="${n}" ${n===10?'selected':''}>${n} teams</option>`).join('')}</select></label><label class="field">Match length<select name="overs"><option value="1">1 over · Quick play</option><option value="2">2 overs</option><option value="5">5 overs</option><option value="10">10 overs</option><option value="20" selected>20 overs</option></select></label><label class="field">Access<select name="private"><option value="false">Public · Listed to all owners</option><option value="true">Private · Invite code required</option></select></label><div class="auction-policy field full"><div><span>TEAM PURSE</span><strong>${formatMoney(TEAM_PURSE)}</strong></div><div><span>MAXIMUM PER PLAYER</span><strong>${formatMoney(PLAYER_CAP)}</strong></div><small>Virtual game funds · Fixed for every new franchise</small></div></div><p class="helper">Every owner claims one franchise. Squads require 11 eligible owned players. Match capacity is enforced by the server.</p><div class="form-footer">${btn('Create tournament','submit-create','dark','plus','type="submit"')}</div></form>`)}
function showJoin(){showModal('Join the competition',`<form id="join-form"><label class="field">Tournament ID or invite code<input name="tournamentId" placeholder="Paste a tournament ID or invite code" required/></label><label class="field">Your franchise name<input name="name" minlength="2" maxlength="40" placeholder="e.g. Coastal Comets" required/></label><div class="form-footer">${btn('Claim your franchise','submit-join','dark','arrow','type="submit"')}</div></form>`)}
function showClaim(){showModal('Name your franchise',`<form id="claim-form"><label class="field">Franchise name<input name="name" minlength="2" maxlength="40" placeholder="e.g. Coastal Comets" required/></label><div class="form-footer">${btn('Claim franchise','submit-claim','dark','shield','type="submit"')}</div></form>`)}
async function openTournament(id:string){requireIdentity(()=>{void (async()=>{try{selected=await api(`/api/tournaments/${encodeURIComponent(id)}`);detailTab='Overview';connectSocket();if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'subscribe',tournamentId:selected!.id}));render()}catch(e){notify((e as Error).message,true)}})()})}
async function act(type:string,extra:Row={},tournamentId=selected?.id){if(!tournamentId)throw new Error('Select a tournament first');const result=await api(`/api/tournaments/${tournamentId}/action`,'POST',{type,...extra});if(result?.teams&&result?.fixtures){selected=result;const index=tournaments.findIndex(t=>t.id===result.id);if(index>=0)tournaments[index]=result;else tournaments.push(result)}else if(type!=='startMatch')selected=await api(`/api/tournaments/${tournamentId}`);render();return result}
async function launchGame(match?:MatchState){if(document.querySelector('.game-shell'))return;const shell=document.createElement('div');shell.className='game-shell';shell.innerHTML='<div class="game-container"></div>';document.body.append(shell);activeMatchId=match?.id||null;sequence=Number(match?.sequence?.[String(user?.id)]??-1);const exit=()=>{if(activeMatchId&&socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'leaveMatch'}));game?.dispose();game=null;activeMatchId=null;shell.remove();render()};try{const {mountGame}=await import('./game.ts');game=mountGame(shell.querySelector('.game-container')!,{mode:match?'online':'practice',matchId:match?.id,userId:user?.id,sendInput:(action:GameInput)=>{if(socket?.readyState!==WebSocket.OPEN){notify('Connection lost. Reconnecting to the match server.',true);return}socket.send(JSON.stringify({type:'input',matchId:activeMatchId,sequence:++sequence,action}))},onExit:exit});if(match){game.update(match);connectSocket();if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'joinMatch',matchId:match.id}))}}catch(e){game=null;shell.remove();notify(`3D rendering could not start: ${(e as Error).message}.${match?' Opening the read-only scorecard.':' Try a supported WebGL browser.'}`,true);if(match)launchScoreboard(match)}}
function launchScoreboard(match:MatchState){if(document.querySelector('.game-shell'))return;const shell=document.createElement('div');shell.className='game-shell scoreboard-only';shell.innerHTML='<header><button class="btn outline" data-score-exit>← Back to clubhouse</button><span class="badge">READ-ONLY LIVE SCORECARD</span></header><div class="scoreboard-content"></div>';document.body.append(shell);activeMatchId=match.id;const exit=()=>{if(activeMatchId&&socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'leaveMatch'}));game?.dispose();game=null;activeMatchId=null;shell.remove();render()};shell.querySelector('[data-score-exit]')?.addEventListener('click',exit);const update=(s:MatchState)=>{const scores=[...s.inningsScores];if(!['INNINGS_BREAK','COMPLETE'].includes(s.phase))scores.push({teamId:s.teams[s.batting].id,runs:s.runs,wickets:s.wickets,balls:s.legalBalls,quotaBalls:s.overs*6,superOver:s.superOver});shell.querySelector('.scoreboard-content')!.innerHTML=`<div class="eyebrow">AUCTION CRICKET PREMIER LEAGUE</div><h1>${esc(s.teams[0].name)} <span>vs</span> ${esc(s.teams[1].name)}</h1><p class="helper">${pretty(s.phase)} · ${s.overs} overs · Independent session ${esc(s.id.slice(0,8))}</p>${s.winnerId?`<div class="champion"><div class="trophy">🏆</div><h2>${esc(s.teams.find(t=>t.id===s.winnerId)?.name)} win</h2><p>Server-verified match result</p></div>`:''}<div class="metrics">${scores.map(i=>`<div class="metric"><div><small>${esc(s.teams.find(t=>t.id===i.teamId)?.name)}${i.superOver?' · SUPER OVER':''}</small><strong>${i.runs}/${i.wickets}</strong><small>${Math.floor(i.balls/6)}.${i.balls%6} overs</small></div></div>`).join('')}</div>${s.teams.map((team,i)=>`<section class="panel" style="margin-bottom:20px"><div class="section-title"><h2>${esc(team.name)}</h2></div><div class="table-wrap"><table><thead><tr><th>Batter</th><th>R</th><th>B</th><th>4s</th><th>6s</th></tr></thead><tbody>${s.batters[i].map(p=>`<tr><td>${esc(team.players.find(x=>x.id===p.playerId)?.name)}${p.out?' · out':''}</td><td>${p.runs}</td><td>${p.balls}</td><td>${p.fours}</td><td>${p.sixes}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}<section class="panel"><div class="section-title"><h2>Ball-by-ball</h2></div>${s.events.slice(-20).reverse().map(e=>`<div class="team-row"><span>${esc(e.text)}</span></div>`).join('')}</section>`};game={dispose(){shell.remove()},update};update(match);connectSocket();if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'joinMatch',matchId:match.id}));}
async function enterMatch(id:string){try{const match=await api(`/api/matches/${id}`);launchGame(match)}catch(e){notify((e as Error).message,true)}}
function bindForms(){const bind=(id:string,handler:(fd:FormData)=>Promise<void>|void)=>{const form=document.getElementById(id) as HTMLFormElement|null;if(!form||form.dataset.bound)return;form.dataset.bound='1';form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector<HTMLButtonElement>('button[type="submit"]');if(submit)submit.disabled=true;try{await handler(new FormData(form))}catch(err){notify((err as Error).message,true)}finally{if(submit)submit.disabled=false}})};
 bind('identity-form',async fd=>{const form=document.getElementById('identity-form') as HTMLFormElement;const mode=form.dataset.authMode||'login';if(mode==='register'&&fd.get('password')!==fd.get('confirmPassword'))throw Error('The passwords do not match.');const name=String(fd.get('name')||'').trim();const result=await api(mode==='guest'?'/api/guest':mode==='register'?'/api/register':'/api/login','POST',mode==='guest'?{name}:{name,password:String(fd.get('password')||'')});form.reset();socket?.close();socket=null;clearTimeout(reconnectTimer);tournaments=[];selected=null;token=result.token;user=result.user;localStorage.setItem('acpl-token',token);localStorage.setItem('acpl-user',JSON.stringify(user));closeModal();await refresh();const next=modalAfter;modalAfter=null;if(next&&user)next()});
 bind('create-form',async fd=>{const t=await api('/api/tournaments','POST',{name:fd.get('name'),teamCount:Number(fd.get('teamCount')),overs:Number(fd.get('overs')),purse:TEAM_PURSE,private:fd.get('private')==='true'});closeModal();tournaments.push(t);selected=t;detailTab='Overview';connectSocket();socket?.readyState===WebSocket.OPEN&&socket.send(JSON.stringify({type:'subscribe',tournamentId:t.id}));render();notify('League created. Claim your franchise and invite the other owners.');showClaim()});
 bind('join-form',async fd=>{let id=String(fd.get('tournamentId')).trim();const known=tournaments.find(t=>t.id===id||t.inviteCode===id);if(known)id=known.id;const joined=await api(`/api/tournaments/${encodeURIComponent(id)}/join`,'POST',{name:fd.get('name'),inviteCode:String(fd.get('tournamentId')).trim()});closeModal();selected=joined;detailTab='Overview';const index=tournaments.findIndex(t=>t.id===joined.id);if(index>=0)tournaments[index]=joined;else tournaments.push(joined);connectSocket();if(socket?.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:'subscribe',tournamentId:joined.id}));render();notify('Your franchise is ready for the auction.')});
 bind('claim-form',async fd=>{await api(`/api/tournaments/${selected!.id}/join`,'POST',{name:fd.get('name')});closeModal();selected=await api(`/api/tournaments/${selected!.id}`);render()});
 bind('bid-form',async fd=>{await act('bid',{amount:selected?.currency==='INR_LAKH'?parseCrores(String(fd.get('amount'))):Number(fd.get('amount')),requestId:crypto.randomUUID()});notify('Bid accepted.')});
 bind('xi-form',async fd=>{await act('selectXI',{playerIds:fd.getAll('players'),captainId:fd.get('captainId'),keeperId:fd.get('keeperId')});notify('Playing XI confirmed. Your franchise is ready.')});
 bind('fixtures-form',async fd=>{await act('fixtures',{format:fd.get('format')});detailTab='Fixtures';render();notify('Tournament schedule generated.')});
 bind('settings-form',async fd=>{const origin=validateBackendOrigin(String(fd.get('apiBase')||''),location.protocol);if(origin!==apiBase){token='';user=null;localStorage.removeItem('acpl-token');localStorage.removeItem('acpl-user');tournaments=[];selected=null}apiBase=origin;localStorage.setItem('acpl-api',apiBase);socket?.close();socket=null;clearTimeout(reconnectTimer);connected=false;render();notify('Connection saved. Sign in or create an account to connect.');});
}
document.addEventListener('click',e=>{const target=(e.target as HTMLElement).closest<HTMLElement>('[data-action],[data-page],[data-tab]');if(!target)return;if(target.closest('form')&&target.getAttribute('type')==='submit')return;e.preventDefault();if(target.dataset.page){nav(target.dataset.page as Page);return}if(target.dataset.tab){detailTab=target.dataset.tab;render();return}const action=target.dataset.action;void (async()=>{try{switch(action){case'menu':document.querySelector('.sidebar')?.classList.toggle('open');break;case'identity':if(user)nav('Settings');else showIdentity();break;case'login':showIdentity('login');break;case'register':showIdentity('register');break;case'guest':showIdentity('guest');break;case'practice-from-auth':modalAfter=null;closeModal();launchGame();break;case'close-modal':modalAfter=null;closeModal();break;case'create':requireIdentity(showCreate);break;case'join':requireIdentity(showJoin);break;case'claim':showClaim();break;case'practice':launchGame();break;case'refresh':requireIdentity(()=>void refresh());break;case'open':await openTournament(target.dataset.id!);break;case'back':selected=null;render();break;case'start-auction':await act('startAuction');detailTab='Auction';render();break;case'finish-auction':await act('finishAuction');detailTab='My Squad';render();break;case'nominate':await act('nominate',{playerId:target.dataset.id});break;case'close-lot':await act('closeLot');break;case'advance-playoffs':await act('advancePlayoffs');detailTab='Playoffs';render();break;case'start-match':{const match=await act('startMatch',{fixtureId:target.dataset.id},target.dataset.tournament||selected?.id);launchGame(match);break}case'enter-match':await enterMatch(target.dataset.id!);break;case'scorecard':launchScoreboard(await api(`/api/matches/${target.dataset.id!}`));break;case'copy-code':await navigator.clipboard.writeText(selected!.inviteCode||selected!.id);notify('Invite code copied.');break;case'test-connection':{const field=document.querySelector<HTMLInputElement>('#settings-form input[name="apiBase"]');const result=document.querySelector<HTMLElement>('#connection-result');if(!field||!result)break;try{const origin=validateBackendOrigin(field.value,location.protocol);result.textContent='Checking the match server…';const health=await probeBackend(origin||location.origin);result.textContent=`Server ready · ${health.activeMatches}/${health.maxMatches} match slots active`;notify('Match server connection verified.');}catch(err){result.textContent=(err as Error).message;throw err;}break;}case'signout':{try{if(token)await api('/api/logout','POST',{});}finally{clearSession();render();}notify('Signed out. This session has been revoked.');break;}}}catch(err){notify((err as Error).message,true)}})()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();modalAfter=null;document.querySelector('.sidebar')?.classList.remove('open')}});
setInterval(()=>{document.querySelectorAll<HTMLElement>('[data-deadline]').forEach(el=>{if(!selected?.auction?.current||selected.auction.current.status!=='OPEN')return;const left=Math.max(0,Math.ceil((Number(el.dataset.deadline)-Date.now())/1000));el.textContent=left?`${left}s remaining · Server clock decides final acceptance`:'Deadline reached · Awaiting authoritative close';})},250);
render();if(token)void refresh();
